const fs = require('fs');
function parseDir(p){
  const out = [];
  for (const f of fs.readdirSync(p).sort()){
    const x = fs.readFileSync(p+'/'+f,'utf8');
    const g = (re) => { const m = x.match(re); return m ? m[1] : null; };
    out.push({
      file: f,
      chave: g(/<chNFe>(\d+)<\/chNFe>/),
      serie: g(/<serie>(\d+)<\/serie>/),
      num: g(/<nNF>(\d+)<\/nNF>/),
      dhEmi: g(/<dhEmi>([^<+]+)/),
      tpAmb: g(/<tpAmb>(\d+)<\/tpAmb>/),
      emitCNPJ: g(/<emit>[\s\S]*?<CNPJ>(\d+)<\/CNPJ>/),
      CRT: g(/<CRT>(\d+)<\/CRT>/),
      destCNPJ: g(/<dest>[\s\S]*?<CNPJ>(\d+)<\/CNPJ>/),
      xNome: g(/<dest>[\s\S]*?<xNome>([^<]+)<\/xNome>/),
      vNF: g(/<vNF>([\d.]+)<\/vNF>/),
      vProd: g(/<vProd>([\d.]+)<\/vProd>/),
      pCBS: g(/<pCBS>([\d.]+)<\/pCBS>/),
      vCBS: g(/<vCBS>([\d.]+)<\/vCBS>/),
      pIBSUF: g(/<pIBSUF>([\d.]+)<\/pIBSUF>/),
      vIBSUF: g(/<vIBSUF>([\d.]+)<\/vIBSUF>/),
      pIBSMun: g(/<pIBSMun>([\d.]+)<\/pIBSMun>/),
      vIBSMun: g(/<vIBSMun>([\d.]+)<\/vIBSMun>/),
      CST: g(/<CST>(\d+)<\/CST>/),
      cClassTrib: g(/<cClassTrib>(\d+)<\/cClassTrib>/),
      cStat: g(/<cStat>(\d+)<\/cStat>/),
      infCpl: g(/<infCpl>([^<]*)<\/infCpl>/),
    });
  }
  return out;
}
const saidas = parseDir('/work/workspace/documents/saidas');
const entradas = parseDir('/work/workspace/documents/entradas');
return {saidas, entradas};

